if (window.dumpNLog) {
  const owner = "JBlitzar";
  const repo = "stomped";

  const apiUrl = `https://api.github.com/repos/${owner}/${repo}`;

  fetch(apiUrl)
    .then((response) => response.json())
    .then((data) => {
      const pushedAtDate = new Date(data.pushed_at);
      alert(
        `Stomped client, made by Some Kid: all hidden skins, hunt mode, bars. Last push: ${pushedAtDate}`
      );
    })
    .catch((error) =>
      alert(
        "Stomped client, made by Some Kid: all hidden skins, hunt mode, bars."
      )
    );
}

document.getElementById("opts").onclick = function () {
  var hMode = confirm("enable hunt mode? ok for yes");
  window.hMode = hMode;
  if (hMode) {
    var number1 = confirm(
      "hunt number one or another by name? (ok for number 1)"
    );
    window.number1 = number1;
    if (!number1) {
      var name = prompt("name to hunt?");
      window.name = name;
    } else {
      window.name = null;
    }
  }
  window.spectate = !confirm(
    "Spectate your killer instead of showing the death screen? Cancel for yes, OK for no"
  );
};
